--
-- Name: view_all_assets; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.view_all_assets AS
 SELECT asset.id,
    asset.layer_id,
    l.name AS layer_name,
    l.geometry_type,
    l.category,
    l.sub_category,
    asset.name,
    asset.reg_number,
    asset.asset_code,
    asset.condition,
    asset.year_built,
    asset.managed_by,
    asset.properties,
    asset.asset_type,
    asset.geom,
    asset.created_at,
    asset.updated_at
   FROM (( SELECT spatial_points.id,
            spatial_points.layer_id,
            spatial_points.name,
            spatial_points.reg_number,
            spatial_points.asset_code,
            spatial_points.condition,
            spatial_points.year_built,
            spatial_points.managed_by,
            spatial_points.properties,
            'Point'::text AS asset_type,
            spatial_points.geom,
            spatial_points.created_at,
            spatial_points.updated_at
           FROM public.spatial_points
        UNION ALL
         SELECT spatial_lines.id,
            spatial_lines.layer_id,
            spatial_lines.name,
            spatial_lines.reg_number,
            spatial_lines.asset_code,
            spatial_lines.condition,
            spatial_lines.year_built,
            spatial_lines.managed_by,
            spatial_lines.properties,
            'Line'::text AS asset_type,
            spatial_lines.geom,
            spatial_lines.created_at,
            spatial_lines.updated_at
           FROM public.spatial_lines
        UNION ALL
         SELECT spatial_polygons.id,
            spatial_polygons.layer_id,
            spatial_polygons.name,
            spatial_polygons.reg_number,
            spatial_polygons.asset_code,
            spatial_polygons.condition,
            spatial_polygons.year_built,
            spatial_polygons.managed_by,
            spatial_polygons.properties,
            'Polygon'::text AS asset_type,
            spatial_polygons.geom,
            spatial_polygons.created_at,
            spatial_polygons.updated_at
           FROM public.spatial_polygons) asset
     JOIN public.layers l ON ((asset.layer_id = l.id)))
  WHERE (l.deleted_at IS NULL);


